VALUES
  (1, '학사', NULL, '2학기 개강 및 수업 운영 안내', '9월 1일 개강합니다.\n\n■ 첫 주 수업은 정상 운영됩니다.\n■ 강의실은 학사정보시스템에서 확인하세요.', '박서연', '학사지원팀', '2026-09-01', 0, 97, '2026-08-18 00:00:00'),
  (2, '채용', NULL, '2학기 현장실습 참여 학생 모집', '2학기 현장실습 참여 학생을 모집합니다.\n\n■ 실습 기간: 9월 ~ 12월\n■ 학점: 최대 6학점 인정\n■ 신청 마감: 9월 3일', '한지우', '산학협력단', '2026-09-03', 0, 134, '2026-08-15 00:00:00'),
  (3, '장학', '근로', '2학기 근로장학생 3차 추가 모집', '2차 모집에서 미충원된 근로지를 추가 모집합니다.\n\n■ 인원: 18명\n■ 근로 시작: 9월 7일\n■ 신청: 학사정보시스템 > 장학 > 근로장학', '김민준', '학생지원팀', '2026-09-04', 0, 158, '2026-08-16 00:00:00'),
  (4, '장학', NULL, '국가장학금 학자금 지원구간 산정 결과 확인 요청', '국가장학금 학자금 지원구간 산정 결과를 확인해 주세요.\n\n■ 확인: 한국장학재단 홈페이지\n■ 이의신청 마감: 9월 2일\n■ 구간이 확정되어야 장학금이 지급됩니다.', '김민준', '학생지원팀', '2026-09-02', 0, 243, '2026-08-14 00:00:00'),
  (5, '장학', NULL, '2학기 교내 장학금 최종 확정자 발표 및 이의신청', '2학기 교내 장학금 확정자를 발표합니다.\n\n■ 확인: 학사정보시스템 > 장학 > 수혜 내역\n■ 이의신청: 8월 24일 ~ 8월 29일\n■ 기간이 지나면 이의신청을 받지 않습니다.', '김민준', '학생지원팀', '2026-08-29', 0, 176, '2026-08-17 00:00:00'),
  (6, '일반', NULL, '교내 헬스장 이용 안내', '재학생은 교내 헬스장을 무료로 이용할 수 있습니다.\n\n■ 운영: 평일 07:00 ~ 21:00\n■ 학생증을 지참하세요.', '윤서아', '생활관운영팀', NULL, 0, 176, '2026-06-25 00:00:00'),
  (7, '일반', NULL, '분실물 보관 및 인계 안내', '분실물은 본관 1층 안내데스크에 보관합니다.\n\n■ 보관 기간: 3개월\n■ 기간이 지나면 폐기합니다.', '최우진', '시설관리팀', NULL, 0, 38, '2026-07-14 00:00:00'),
  (8, '일반', NULL, '교내 셔틀버스 2학기 운행 일정', '2학기 셔틀버스 운행 일정입니다.\n\n■ 운행: 08:00 ~ 19:00, 20분 간격\n■ 노선: 지하철역 ↔ 정문 ↔ 생활관', '최우진', '시설관리팀', NULL, 0, 231, '2026-07-20 00:00:00'),
  (9, '일반', NULL, '학생증 재발급 안내', '학생증 분실 시 재발급 절차입니다.\n\n■ 신청: 본관 1층 학사지원팀\n■ 수수료: 5,000원\n■ 발급 기간: 약 5일', '송예린', '학사지원팀', NULL, 0, 144, '2026-07-27 00:00:00'),
  (10, '일반', NULL, '교내 흡연 구역 조정 안내', '교내 흡연 구역이 조정되었습니다.\n\n■ 지정 구역: 후문 옆, 체육관 뒤편\n■ 그 외 구역은 금연입니다.', '최우진', '시설관리팀', NULL, 0, 52, '2026-08-05 00:00:00'),
  (11, '행사', NULL, '학과별 학술제 일정 안내', '학과별 학술제 일정을 안내합니다.\n\n■ 기간: 11월 2일 ~ 11월 13일\n■ 자세한 일정은 학과 공지를 확인하세요.', '한지우', '산학협력단', NULL, 0, 59, '2026-06-24 00:00:00'),
  (12, '행사', NULL, '신입생 멘토링 프로그램 멘토 모집', '신입생을 도와줄 선배 멘토를 모집합니다.\n\n■ 자격: 2학년 이상\n■ 혜택: 봉사시간, 활동비 지급', '이도현', '학생지원팀', '2026-08-20', 0, 107, '2026-06-26 00:00:00'),
  (13, '행사', NULL, '교내 사진 공모전 개최', '캠퍼스를 주제로 한 사진 공모전입니다.\n\n■ 접수: 9월 20일까지\n■ 시상: 대상 30만원', '이도현', '총학생회', '2026-09-20', 0, 83, '2026-07-12 00:00:00'),
  (14, '행사', NULL, '독서 마라톤 참가자 모집', '한 학기 동안 책을 읽고 기록하는 프로그램입니다.\n\n■ 기간: 9월 ~ 12월\n■ 시상: 상위 20명에게 도서 상품권', '윤서아', '학술정보원', '2026-09-30', 0, 64, '2026-07-26 00:00:00'),
  (15, '행사', NULL, '가을 축제 공연팀 오디션', '축제 무대에 설 공연팀을 모집합니다.\n\n■ 오디션: 9월 4일(금)\n■ 신청: 9월 1일까지', '이도현', '총학생회', '2026-09-01', 0, 128, '2026-08-08 00:00:00'),
  (16, '채용', NULL, '해외 취업 설명회 안내', '일본 IT 기업 해외 취업 설명회입니다.\n\n■ 일시: 8월 21일(금) 14:00\n■ 장소: 본관 대강당', '오세훈', '국제교류팀', NULL, 0, 98, '2026-06-27 00:00:00'),
