INSERT INTO pages
(slug, menu, title, body, sort_order)
VALUES
  ('greeting', '대학안내', '총장 인사말', '인하공업전문대학 홈페이지를 찾아주신 여러분을 환영합니다.\n\n우리 대학은 실무 중심 교육으로 산업 현장이 필요로 하는 인재를 길러왔습니다. 이론에 머무르지 않고 직접 만들고 실험하며 배우는 것, 그것이 우리가 지켜온 방식입니다.\n\n젊음의 앞이 늘 당당할 수 있도록 함께 걷겠습니다.', 1),
  ('history', '대학안내', '대학 연혁', '1958년  개교\n1972년  전문학교로 개편\n1998년  전문대학으로 교명 변경\n2012년  창의관 준공, 산학협력단 출범\n2020년  LINC 사업 선정\n2026년  개교 68주년', 2),
  ('vision', '대학안내', '교육목표 및 비전', '미래 사회를 선도하는 전문 인재 양성을 목표로 합니다.\n\n■ 교육목표\n- 현장에서 바로 통하는 실무 역량\n- 스스로 배우고 고쳐 나가는 태도\n- 함께 일할 줄 아는 협업 능력\n\n■ 인재상\n배운 것을 직접 만들어 보는 사람, 문제를 끝까지 붙들고 해결하는 사람을 기릅니다.\n\n■ 비전\n산업 현장과 가장 가까운 대학, 졸업생이 자랑스러워하는 대학이 되겠습니다.', 3),
  ('campus', '대학안내', '캠퍼스 안내', '본관        행정실, 대강의실, 학생지원팀\n창의관      실습실, 컴퓨터실, 스튜디오\n학술정보원  도서관, 열람실, 그룹 스터디룸\n생활관      기숙사 A동 · B동\n체육관      실내 체육관, 헬스장', 4),
  ('location', '대학안내', '오시는 길', '지하철: 1호선 도원역에서 도보 12분\n버스: 8, 15, 24, 519번 정류장 하차\n주차: 제1주차장 이용 (제2주차장은 8월 28일까지 공사)', 5),
  ('departments', '학과안내', '학과 목록', '컴퓨터정보공학과\n기계공학과\n전기전자공학과\n건축인테리어과\n경영정보과\n시각디자인과', 1),
  ('dept-cs', '학과안내', '컴퓨터정보공학과', '소프트웨어 개발과 정보 시스템 운영 능력을 갖춘 실무 인재를 기릅니다.\n\n주요 교과목\n- 프로그래밍 기초 / 자료구조\n- 웹 프론트엔드 / 백엔드 개발\n- 데이터베이스 / 네트워크\n- 캡스톤 디자인\n\n진로: 웹 개발자, 시스템 엔지니어, 데이터 분석가', 2),
  ('dept-me', '학과안내', '기계공학과', '설계부터 가공까지 전 과정을 다루는 기계 전문 인력을 양성합니다.\n\n주요 교과목\n- 기계 제도 / CAD\n- 재료역학 / 유체역학\n- CNC 가공 실습\n- 자동화 시스템', 3),
  ('admission-susi', '입학안내', '수시 모집', '원서 접수: 9월 9일 ~ 9월 12일\n서류 마감: 9월 15일\n합격 발표: 11월 1일\n\n전형 방법: 학생부 교과 100%', 1),
  ('admission-jeongsi', '입학안내', '정시 모집', '원서 접수: 12월 29일 ~ 1월 2일\n합격 발표: 1월 20일\n\n전형 방법: 수능 100% 또는 학생부 100% 중 선택', 2),
  ('admission-scholarship', '입학안내', '신입생 장학 혜택', '성적우수 장학: 등록금 전액 ~ 50%\n지역인재 장학: 등록금 30%\n특기자 장학: 등록금 30% ~ 50%\n\n중복 수혜는 불가하며 가장 유리한 항목이 자동 적용됩니다.', 3),
  ('calendar', '학사안내', '학사 일정 안내', '9월 1일    2학기 개강\n9월 19일   수강 정정 마감\n10월 20일  중간고사 시작\n11월 10일  기말 수강 취소 마감\n12월 15일  기말고사 시작\n12월 19일  종강\n\n달력으로 보려면 홈의 학사일정 카드를 누르세요.', 1),
  ('course', '학사안내', '수강 신청 안내', '수강 신청은 학사정보시스템에서 진행합니다.\n\n1. 학사정보시스템 로그인\n2. 수강신청 > 개설 강좌 조회\n3. 장바구니 담기 후 신청\n\n학기당 최대 21학점까지 신청할 수 있습니다.', 2),
  ('graduation', '학사안내', '졸업 요건', '총 이수 학점: 80학점 이상\n전공 필수: 45학점 이상\n교양 필수: 15학점 이상\n\n졸업 인증: 전공 자격증 1개 이상 또는 캡스톤 디자인 이수', 3),
  ('scholarship', '대학생활', '장학제도 안내', '교내 장학\n- 성적우수 / 근로 / 봉사 / 생활지원\n\n교외 장학\n- 국가장학금 Ⅰ·Ⅱ 유형 / 국가근로장학금 / 지자체 장학\n\n신청 방법은 공지사항의 장학 카테고리를 확인하세요.', 1),
  ('dorm', '대학생활', '생활관 안내', '생활관(기숙사) 안내입니다.\n\n생활관 A동  남학생 2인실 · 4인실\n생활관 B동  여학생 2인실 · 4인실\n\n비용: 학기당 95만원 (식비 별도)\n선발 기준: 통학 거리, 소득분위, 직전 학기 성적', 2),
  ('club', '대학생활', '동아리 안내', '학술  프로그래밍, 로보틱스, 창업\n체육  축구, 농구, 클라이밍\n문화  밴드, 사진, 연극\n봉사  지역 아동센터 교육 봉사', 3),
  ('forms', '정보광장', '학사 서식', '휴학 신청서\n복학 신청서\n전공 변경 신청서\n성적 정정 요청서\n증명서 발급 신청서\n\n서식은 학사지원팀에서 내려받을 수 있습니다.', 1),
  ('faq', '정보광장', '자주 묻는 질문', 'Q. 증명서는 어디서 발급받나요?\nA. 본관 1층 무인 발급기 또는 학사정보시스템에서 온라인 발급이 가능합니다.\n\nQ. 수강 정정은 몇 번까지 가능한가요?\nA. 정정 기간 중에는 횟수 제한 없이 가능합니다.\n\nQ. 장학금 신청 결과는 언제 나오나요?\nA. 신청 마감 후 약 3주 뒤 학사정보시스템에서 확인할 수 있습니다.', 2),
  ('privacy', '정보광장', '개인정보처리방침', '본 사이트는 학습 목적으로 제작된 비공식 사이트입니다.\n실제 개인정보를 수집하지 않으며, 게시된 공지는 예시 데이터입니다.', 3);
